def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        current_time = op[1]

        # Remove expired entries
        expired_keys = [k for k, (v, wt) in cache.items() if current_time >= wt + ttl]
        for k in expired_keys:
            del cache[k]

        if op[0] == 'put':
            key, value = op[2], op[3]

            # If key already exists, remove it (we'll re-add as most recent)
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU (first item)
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry as most recently used
            cache[key] = (value, current_time)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Make it most recently used
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

